/*
 * main.cjs - Electron main process of the Slyy Desktop wireframes app.
 *
 * One window, local files only. The renderer is sandboxed, has no Node
 * access and cannot navigate away; https links open in the system browser.
 * Screens and their order come from out/renderer/screens.json, generated by
 * scripts/build_screens.mjs from the wireframe canvas export.
 *
 * App lifecycle like the real app: move to Applications on first launch
 * (install.cjs), in-app updates (updater.cjs), and an offer to clean up the
 * installer and downloaded updates after install and update (cleanup.cjs).
 */
const { app, BrowserWindow, Menu, session, shell } = require("electron");
const fs = require("node:fs");
const path = require("node:path");
const { createState } = require("./state.cjs");
const { createUpdater } = require("./updater.cjs");
const { offerCleanup } = require("./cleanup.cjs");
const { offerMoveToApplications } = require("./install.cjs");
const core = require("./lifecycle_core.cjs");

const RENDERER_DIR = path.join(__dirname, "..", "renderer");
const INDEX_HTML = path.join(RENDERER_DIR, "index.html");

// productName is "Slyy Desktop", but "~/Library/Application Support/Slyy
// Desktop" may hold data of the earlier Slyy Desktop product. Keep this
// app's Chromium profile and state under its own bundle id instead. Must
// run before the single-instance lock, which lives in userData.
app.setPath("userData", path.join(app.getPath("appData"), "ai.slyy.desktop.wireframes"));

/** Screen list for the menu; an unreadable index just yields no entries. */
function loadScreens() {
	try {
		const index = JSON.parse(fs.readFileSync(path.join(RENDERER_DIR, "screens.json"), "utf8"));
		return Array.isArray(index.screens) ? index.screens : [];
	} catch (err) {
		console.error("[desktop-wireframes] cannot read screens.json:", err);
		return [];
	}
}

let mainWindow = null;
let screensCache = [];
let state = null;
const updater = createUpdater({ getWindow: () => mainWindow, onChange: () => buildMenu(screensCache) });

/** Manual "Clean Up Installer Files…": also looks at ~/Downloads. */
function cleanUpNow() {
	return offerCleanup(mainWindow, {
		reason: "manual",
		scanDownloads: true,
		includeUpdateCache: !updater.hasPendingUpdate(),
	});
}

/** App menu, laid out like the real app's (About, Check for Updates…, …). */
function appMenu() {
	return {
		label: app.name,
		submenu: [
			{ role: "about" },
			updater.menuItem(),
			{ type: "separator" },
			{ id: "clean-up-now", label: "Clean Up Installer Files…", click: () => cleanUpNow() },
			{
				id: "offer-cleanup",
				label: "Offer Clean-Up After Install and Update",
				type: "checkbox",
				checked: state ? state.get("offerCleanup") : true,
				click: (item) => state?.set("offerCleanup", item.checked),
			},
			{ type: "separator" },
			{ role: "services" },
			{ type: "separator" },
			{ role: "hide" },
			{ role: "hideOthers" },
			{ role: "unhide" },
			{ type: "separator" },
			{ role: "quit" },
		],
	};
}

/**
 * After the first launch of a new version: remember it, and offer to clean
 * up the installer DMG and the downloaded update.
 */
async function afterInstallOrUpgrade() {
	const kind = core.launchKind(state.get("lastVersion"), app.getVersion());
	state.set("lastVersion", app.getVersion());
	if (!kind || !app.isPackaged || !state.get("offerCleanup")) return;
	await offerCleanup(mainWindow, {
		reason: kind,
		includeUpdateCache: kind === "upgrade",
		onDontAskAgain: () => {
			state.set("offerCleanup", false);
			buildMenu(screensCache);
		},
	});
}

/** Send a menu command to the renderer (see preload.cjs). */
function command(cmd) {
	if (mainWindow && !mainWindow.isDestroyed()) mainWindow.webContents.send("shell:command", cmd);
}

function buildMenu(screens) {
	screensCache = screens;
	const screenItems = screens.map((s, i) => ({
		label: s.title,
		// Cmd+1..Cmd+9 for the first nine artboards.
		accelerator: i < 9 ? `CmdOrCtrl+${i + 1}` : undefined,
		click: () => command({ type: "navigate", target: s.file }),
	}));
	const template = [
		appMenu(),
		{ role: "editMenu" },
		{
			label: "Screens",
			submenu: [
				{ label: "Overview", accelerator: "CmdOrCtrl+0", click: () => command({ type: "navigate", target: "overview" }) },
				{ type: "separator" },
				...screenItems,
			],
		},
		{
			label: "Go",
			submenu: [
				{ label: "Back", accelerator: "CmdOrCtrl+[", click: () => command({ type: "back" }) },
				{ label: "Forward", accelerator: "CmdOrCtrl+]", click: () => command({ type: "forward" }) },
				{ type: "separator" },
				{
					label: "Start Over",
					accelerator: "CmdOrCtrl+Shift+R",
					click: () => mainWindow?.webContents.reloadIgnoringCache(),
				},
			],
		},
		{
			label: "View",
			submenu: [
				{ role: "resetZoom" },
				{ role: "zoomIn" },
				{ role: "zoomOut" },
				{ type: "separator" },
				{ role: "togglefullscreen" },
				// DevTools only in unpackaged runs.
				...(app.isPackaged ? [] : [{ type: "separator" }, { role: "toggleDevTools" }]),
			],
		},
		{ role: "windowMenu" },
	];
	Menu.setApplicationMenu(Menu.buildFromTemplate(template));
}

function createWindow() {
	mainWindow = new BrowserWindow({
		width: 1360,
		height: 860,
		minWidth: 1024,
		minHeight: 680,
		backgroundColor: "#f4f4f2",
		title: "Slyy Desktop",
		show: false,
		webPreferences: {
			preload: path.join(__dirname, "preload.cjs"),
			contextIsolation: true,
			sandbox: true,
			nodeIntegration: false,
			webSecurity: true,
			spellcheck: false,
			devTools: !app.isPackaged,
		},
	});
	mainWindow.once("ready-to-show", () => mainWindow.show());
	mainWindow.on("closed", () => {
		mainWindow = null;
	});
	mainWindow.loadFile(INDEX_HTML);
}

// Lock every web contents down: no navigation away from index.html, no new
// windows, https links go to the system browser only.
app.on("web-contents-created", (_event, contents) => {
	contents.on("will-navigate", (event) => event.preventDefault());
	contents.setWindowOpenHandler(({ url }) => {
		if (/^https:\/\//i.test(url)) shell.openExternal(url);
		return { action: "deny" };
	});
});

if (!app.requestSingleInstanceLock()) {
	app.quit();
} else {
	app.on("second-instance", () => {
		if (mainWindow) {
			if (mainWindow.isMinimized()) mainWindow.restore();
			mainWindow.focus();
		}
	});

	app.whenReady().then(async () => {
		// A wireframe app needs no camera, mic, notifications or anything else.
		session.defaultSession.setPermissionRequestHandler((_wc, _perm, cb) => cb(false));
		session.defaultSession.setPermissionCheckHandler(() => false);
		// Opened from the DMG: move to Applications first; it relaunches.
		if (await offerMoveToApplications()) return;
		state = createState(app.getPath("userData"));
		buildMenu(loadScreens());
		createWindow();
		app.on("activate", () => {
			if (BrowserWindow.getAllWindows().length === 0) createWindow();
		});
		mainWindow.once("ready-to-show", () => {
			afterInstallOrUpgrade()
				.catch((err) => console.error("[desktop-wireframes] clean-up offer failed:", err))
				.finally(() => updater.start());
		});
	});

	app.on("window-all-closed", () => {
		if (process.platform !== "darwin") app.quit();
	});
}
